def save_rights():
 rows=[]
 for k,f in F.items():
  p='assets/img/n02/alpha/codex/'+f['file'];rows.append(dict(id=k,title=f['alt'],path=p,sha256=hashlib.sha256((ROOT/p).read_bytes()).hexdigest(),original_url=f['url'],source_url=f['page'],author=f['author'],license=f['license'],license_url=f['license_url'],source_page_sha256=hashlib.sha256(Path(f['proof']).read_bytes()).hexdigest(),source_page_read='Description, auteur, original, licence propre à la figure ; cache effectivement relu',original_unmodified=True,annotations=[dict(number=i,x_percent=x,y_percent=y,label=l) for i,((x,y),l) in enumerate(zip(f['coords'],f['labels']),1)],visual_review='Original réellement vu par astra_nephrologie le2026-11-02 ; annotations à recontrôler dans le rendu final',limitations=f['lim']))
